export function normalizeCodewordWord(
  raw: string,
  alphabet: Set<string>,
  language?: string
): string | null {
  if (!raw) return null;
  // Keep accented letters on the word; coding alphabet is A–Z via baseCodeLetter.
  const upper = localeUpperCase(normalizePuzzleText(raw), language);
  const letters = segmentGraphemes(upper).filter((g) => isLetterGrapheme(g));
  if (letters.length < 3) return null;
  for (const ch of letters) {
    const base = baseCodeLetter(ch, language);
    if (!base || !alphabet.has(base)) return null;
  }
  return letters.join('');
}

export function buildCodewordDictionary(args: {
  language: string;
  alphabet: string[];
  words: string[];
  minLength?: number;
  maxLength?: number;
}): CodewordDictionary {
  const locale = resolvePuzzleLocale(args.language);
  const alphabet = args.alphabet.map((c) => localeUpperCase(normalizePuzzleText(c), locale));
  const alphaSet = new Set(alphabet);
  const minLen = args.minLength ?? 3;
  const maxLen = args.maxLength ?? 15;
  const seen = new Set<string>();
  const words: string[] = [];
  for (const raw of args.words) {
    const w = normalizeCodewordWord(raw, alphaSet, locale);
    if (!w) continue;
    const len = segmentGraphemes(w).length;
    if (len < minLen || len > maxLen) continue;
    if (seen.has(w)) continue;
    seen.add(w);
    words.push(w);
  }
  return { language: args.language, alphabet, words };
}

export function getEnglishCodewordDictionary(): CodewordDictionary {
  return buildCodewordDictionary({
    language: 'en',
    alphabet: ENGLISH_ALPHABET,
    words: ENGLISH_RAW_WORDS,
  });
}

export function getFrenchCodewordDictionary(): CodewordDictionary {
  // Word list is French; coding alphabet stays A–Z so the key box remains 2×13.
  return buildCodewordDictionary({
    language: 'fr',
    alphabet: ENGLISH_ALPHABET,
    words: FRENCH_RAW_WORDS,
  });
}

export function getGermanCodewordDictionary(): CodewordDictionary {
  return buildCodewordDictionary({
    language: 'de',
    alphabet: ENGLISH_ALPHABET,
    words: GERMAN_RAW_WORDS,
  });
}

export function getSpanishCodewordDictionary(): CodewordDictionary {
  return buildCodewordDictionary({
    language: 'es',
    alphabet: ENGLISH_ALPHABET,
    words: SPANISH_RAW_WORDS,
  });
}

export function getCodewordDictionary(language: string): CodewordDictionary {
  const locale = resolvePuzzleLocale(language);
  if (locale === 'fr') return getFrenchCodewordDictionary();
  if (locale === 'de') return getGermanCodewordDictionary();
  if (locale === 'es') return getSpanishCodewordDictionary();
  return getEnglishCodewordDictionary();
}

export type PatternIndex = {
  wordsByLength: Map<number, string[]>;
  /** pattern key e.g. "C?T" -> matching words */
  patternCache: Map<string, string[]>;
};

export function buildPatternIndex(dict: CodewordDictionary): PatternIndex {
  const wordsByLength = new Map<number, string[]>();
  for (const w of dict.words) {
    const len = segmentGraphemes(w).length;
    const list = wordsByLength.get(len);
    if (list) list.push(w);
    else wordsByLength.set(len, [w]);
  }
  return { wordsByLength, patternCache: new Map() };
}

export function wordsMatchingPattern(
  index: PatternIndex,
  pattern: string
): string[] {
  const cached = index.patternCache.get(pattern);
  if (cached) return cached;
  const patternChars = segmentGraphemes(pattern);
  const pool = index.wordsByLength.get(patternChars.length) ?? [];
  const out: string[] = [];
  for (const w of pool) {
    const wordChars = segmentGraphemes(w);
    let ok = true;
    for (let i = 0; i < patternChars.length; i++) {
      const p = patternChars[i]!;
      if (p !== '?' && p !== wordChars[i]) {
        ok = false;
        break;
      }
    }
    if (ok) out.push(w);
  }
  index.patternCache.set(pattern, out);
  return out;
}
